/*
Day #21/24 Curvilinear
https://openprocessing.org/sketch/2409783
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let sc1, sc2;
const FPS = 30; // frames per second
const FPT = 60; // frames per transition

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(FPS);
	describe("curvilinear coordinate system made of lerping two bezier curves warping into new beziers");
	colorMode(HSB);
	background("rgb(2,2,12)");
	noFill();

	sc1 = genBezs(2);
	sc2 = genBezs(2);
	if (!isLooping()) redraw();
}

function genBezs(n = 1) {
	let bezs = [];
	for (let i = 0; i < n; i++) {
		const p1 = {x: 0, y: ~~(random(0, 0.3) * height)};
		const p2 = {x: ~~(random(0.25, 0.6)*width), y: ~~(random(1) * height)};
		const p3 = {x: ~~(random(0.4, 0.75)*width), y: ~~(random(1) * height)};
		const p4 = {x: width, y: ~~(random(0.7, 1)*height)};
		const pts = [p1, p2, p3, p4];
		for (const p of pts) {
			p.x = ~~random(width);
			p.y = ~~random(height);
		}
		bezs[i] = pts;
	}
	return bezs;
}

function draw() {
	background("rgb(2,2,8)");
	if (frameCount % FPT === 0) {
		[sc1,sc2] = [sc2, genBezs(2)];
	}
	const t = fract(frameCount / FPT);
	const bez = lerpBezs(sc1, sc2, t);
	// drawTangents(bez);

	strokeWeight(2);	
	if (true && bez.length === 2) {
		const num = 10;
		for (let i = 0; i <= num; i++) {
			var pts = lerpBez(bez[0], bez[1], i/num);

			var p1, p2, p3, p4;
			[p1, p2, p3, p4] = pts;

			const fc = 0;
			const x = bezierPoint(p1.x, p2.x, p3.x, p4.x, fc);
			const y = bezierPoint(p1.y, p2.y, p3.y, p4.y, fc);

			// Top-right tangent line.
			// Scale the tangent point to draw a shorter line.

			let tx = 2 * bezierTangent(p1.x, p2.x, p3.x, p4.x, fc);
			let ty = 2 * bezierTangent(p1.y, p2.y, p3.y, p4.y, fc);
			const vec = createVector(tx, ty).normalize().mult(0.3*max(width, height)); // mult(2*max(width, height));
			const ang = vec.heading();
			const clrDevi = 60 * (noise((x+tx)/1234, (y+ty)/4321, frameCount/22)-0.5);
			stroke(~~(ang/TWO_PI*360 + clrDevi + 360) % 360, 75, 75, 0.5);
			// line(x + vec.x, y + vec.y, x - vec.x, y - vec.y);

			bezier(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, p4.x, p4.y)

			const b1 = bez[0];
			const b2 = bez[1];
			line(
				bezierPoint(b1[0].x, b1[1].x, b1[2].x, b1[3].x, i/num),
				bezierPoint(b1[0].y, b1[1].y, b1[2].y, b1[3].y, i/num),
				bezierPoint(b2[0].x, b2[1].x, b2[2].x, b2[3].x, i/num),
				bezierPoint(b2[0].y, b2[1].y, b2[2].y, b2[3].y, i/num)
			);
		}
		// // noLoop() removed for animation
	}

}

function lerpBezs(sc1, sc2, t) {
	var bezs = [];
	for (let i = 0; i < sc1.length; i++) {
		pts = lerpBez(sc1[i], sc2[i], t);
		bezs.push(pts);
	}
	return bezs;
}

function lerpBez(bz1, bz2, t) {
	var pts = [];
	for (let i = 0; i < 4; i++) {
		const p = {x: lerp(bz1[i].x, bz2[i].x, t), y: lerp(bz1[i].y, bz2[i].y, t)};
		pts[i] = p;
	}
	return pts;
}

function drawTangents(bezs) {
	// https://p5js.org/reference/p5/bezierTangent/
	for (let bez of bezs) {
		var p1, p2, p3, p4;
		[p1, p2, p3, p4] = bez;

		strokeWeight(3);
		stroke("rgba(139,0,0,0.5)");
		// bezier(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, p4.x, p4.y)

		strokeWeight(1);
		stroke(255, 96);
		for (let f = 0; f <= 1; f += 0.004) {
			var x = bezierPoint(p1.x, p2.x, p3.x, p4.x, f);
			var y = bezierPoint(p1.y, p2.y, p3.y, p4.y, f);

			// Top-right tangent line.
			// Scale the tangent point to draw a shorter line.
			var tx = 2 * bezierTangent(p1.x, p2.x, p3.x, p4.x, f);
			var ty = 2 * bezierTangent(p1.y, p2.y, p3.y, p4.y, f);
			var vec = createVector(tx, ty).normalize().mult(0.3*max(width, height)); // mult(2*max(width, height));
			var ang = vec.heading();
			var clrDevi = 60 * (noise((x+tx)/1234, (y+ty)/4321, frameCount/22)-0.5);
			stroke(~~(ang/TWO_PI*360 + clrDevi + 360) % 360, 75, 75, 0.25);
			line(x + vec.x, y + vec.y, x - vec.x, y - vec.y);
		}
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}
function doubleClicked() {
	if (mouseButton === LEFT) setup();
}
function mousePressed() {
	if (mouseButton !== LEFT) return;
	  if (isLooping()) {
    // noLoop() removed for animation
  } else {
    loop();
  }
}
